/// A span of a chat, from `first_message_id` to `last_message_id` (both inclusive).
class OutlineChapter {
  final String id;
  final String title;
  final String summary;

  /// The sections' segmentation entries, in order: boundary choices, not conclusions.
  final List<String> decisions;

  /// True while the chapter is still open.
  final bool ongoing;
  final String firstMessageId;
  final String lastMessageId;

  /// RFC 3339 time of the first anchor message.
  final String startedAt;

  /// RFC 3339 time of the last anchor message; None while the chapter is open.
  final String? endedAt;
  final List<OutlineSection> sections;

  const OutlineChapter({
    required this.id,
    required this.title,
    required this.summary,
    required this.decisions,
    required this.ongoing,
    required this.firstMessageId,
    required this.lastMessageId,
    required this.startedAt,
    this.endedAt,
    required this.sections,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      title.hashCode ^
      summary.hashCode ^
      decisions.hashCode ^
      ongoing.hashCode ^
      firstMessageId.hashCode ^
      lastMessageId.hashCode ^
      startedAt.hashCode ^
      endedAt.hashCode ^
      sections.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is OutlineChapter &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          title == other.title &&
          summary == other.summary &&
          decisions == other.decisions &&
          ongoing == other.ongoing &&
          firstMessageId == other.firstMessageId &&
          lastMessageId == other.lastMessageId &&
          startedAt == other.startedAt &&
          endedAt == other.endedAt &&
          sections == other.sections;
}

