/// Dev replay status (`vault_agent::replay::ReplayStatus`). Replay needs `NOTES_DEV_REPLAY=1`.
class ReplayStatus {
  /// The recorded user messages, in send order.
  final List<String> userTexts;
  final int completedUsers;

  /// `waiting`, `running`, `paused`, `stopped`, `complete` or `error`.
  final String state;
  final String? error;

  const ReplayStatus({
    required this.userTexts,
    required this.completedUsers,
    required this.state,
    this.error,
  });

  @override
  int get hashCode =>
      userTexts.hashCode ^
      completedUsers.hashCode ^
      state.hashCode ^
      error.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ReplayStatus &&
          runtimeType == other.runtimeType &&
          userTexts == other.userTexts &&
          completedUsers == other.completedUsers &&
          state == other.state &&
          error == other.error;
}

